def parse_tutar(tutar_sirasi):
    """
    Tutar string'ini sayıya çevirir.
    - ₺, TL ve boşluklar kaldırılır
    - Hem . hem , varsa: . binlik, , ondalık
    - Sadece , varsa: ondalık ayırıcı
    - Sadece . varsa: noktadan sonra 3 rakam varsa binlik, değilse ondalık
    - Geçerli sayı döner, değilse None
    """
    if tutar_sirasi is None:
        return None

    # Sayı zaten ise
    if isinstance(tutar_sirasi, (int, float)):
        return float(tutar_sirasi)

    # String ise
    s = str(tutar_sirasi)

    # ₺ ve TL karakterlerini kaldır
    s = s.replace('₺', '').replace('TL', '').replace('tl', '').replace('Tl', '').strip()

    if not s or s.isspace():
        return None

    nokta_sayisi = s.count('.')
    virgul_sayisi = s.count(',')

    if nokta_sayisi == 0 and virgul_sayisi == 0:
        try:
            return float(s)
        except ValueError:
            return None

    # Hem nokta hem virgül var
    if nokta_sayisi > 0 and virgul_sayisi > 0:
        nokta_indis = s.rfind('.')
        virgul_indis = s.rfind(',')
        if nokta_indis < virgul_indis:
            # . binlik, , ondalık
            s = s.replace('.', '').replace(',', '.')
        else:
            # Virgül daha geç, belki . binlik?
            # Noktanın ardından 3 rakam var mı?
            noktanin_sonu = s[nokta_indis+1:]
            if len(noktanin_sonu) == 3 and noktanin_sonu.isdigit():
                # Nokta binlik ayırıcı
                s = s.replace('.', '').replace(',', '.')
            else:
                # Virgül ondalık
                s = s.replace(',', '')
                try:
                    return float(s)
